CREATE FUNCTION dg_native_order_history(target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;orders_value jsonb;active_value text;current_value text;
BEGIN
 meta:=dg_native_order_context('party',target,session_value,token_value);
 SELECT current_order.id INTO active_value FROM restaurant_orders current_order JOIN _dg_native_order_origins origin ON origin.order_id=current_order.id WHERE current_order.party_id=target AND current_order.settlement_status='unsettled' AND current_order.status NOT IN('closed','cancelled') ORDER BY current_order.created_at DESC,current_order.id DESC LIMIT 1;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',current_order.id,'number',current_order.number,'version',current_order.version,'contentVersion',current_order.content_version,'status',current_order.status,'settlementStatus',current_order.settlement_status,'totalMinor',coalesce((SELECT sum((line.quantity-line.cancelled_quantity)*line.unit_price_minor) FROM restaurant_order_lines line WHERE line.order_id=current_order.id),0),'createdAt',current_order.created_at,'updatedAt',current_order.updated_at) ORDER BY current_order.created_at DESC,current_order.id DESC),'[]') INTO orders_value FROM(SELECT current_order.* FROM restaurant_orders current_order JOIN _dg_native_order_origins origin ON origin.order_id=current_order.id WHERE current_order.party_id=target ORDER BY current_order.created_at DESC,current_order.id DESC LIMIT 100) current_order;
 current_value:=coalesce(active_value,orders_value->0->>'id');RETURN jsonb_build_object('partyId',target,'currentOrderId',current_value,'activeOrderId',active_value,'orders',orders_value,'connection',dg_native_order_pos_project(meta->>'restaurantId',false)-ARRAY['canManage','scenario'],'automatic',session_value IS NULL OR dg_native_order_source(meta,target));
END;$dg$;
REVOKE ALL ON FUNCTION dg_native_order_history(text,text,text) FROM PUBLIC;
